import cmath, itertools
from math import gcd
from sympy import factorint, primitive_root, totient, mobius, divisors
def characters(q):
    """All Dirichlet characters mod q, each as a list of values chi(0..q-1)."""
    comps = []
    for p, k in factorint(q).items():
        pk = p**k
        if p == 2:
            if k >= 2:
                comps.append((pk, 2, lambda n: 0 if n % 4 == 1 else 1))
            if k >= 3:
                m = 2**(k-2); tab = {}; x = 1
                for e in range(m): tab[x] = e; x = x*5 % pk
                comps.append((pk, m, lambda n, pk=pk, tab=tab: tab[(n if n % 4 == 1 else -n) % pk]))
        else:
            g = primitive_root(pk); m = pk//p*(p-1); tab = {}; x = 1
            for e in range(m): tab[x] = e; x = x*g % pk
            comps.append((pk, m, lambda n, pk=pk, tab=tab: tab[n % pk]))
    out = []
    for ks in itertools.product(*[range(m) for _, m, _ in comps]):
        vals = []
        for n in range(q):
            if gcd(n, q) != 1:
                vals.append(0); continue
            z = 1
            for (pk, m, lg), kk in zip(comps, ks):
                z *= cmath.exp(2j*cmath.pi*kk*lg(n)/m)
            vals.append(z)
        out.append(vals)
    return out
def conductor(chi, q):
    for d in divisors(q):
        if all(abs(chi[n] - 1) < 1e-9 for n in range(q) if gcd(n, q) == 1 and n % d == 1 % d):
            return d
def close(a, b, eps=1e-9): return abs(a - b) < eps

for q in range(1, 41):
